package main

import (
	"errors"
	"strings"
)

const (
	maxCartItems               = 50
	maxQuantityPerItem         = 99
	maxTotalCartQuantity       = 500
	flat100DiscountPaise int64 = 10000
)

var productsByID = map[string]Product{
	"notebook": {ID: "notebook", Name: "Notebook", PricePaise: 4999},
	"mug":      {ID: "mug", Name: "Coffee Mug", PricePaise: 29900},
	"bag":      {ID: "bag", Name: "Canvas Bag", PricePaise: 129900},
}

func listProducts() []Product {
	return []Product{
		productsByID["notebook"],
		productsByID["mug"],
		productsByID["bag"],
	}
}

func calculateCheckout(request CheckoutRequest) (CheckoutResponse, error) {
	if len(request.Items) == 0 {
		return CheckoutResponse{}, errors.New("cart must contain at least one item")
	}
	if len(request.Items) > maxCartItems {
		return CheckoutResponse{}, errors.New("cart contains too many items")
	}

	var subtotalPaise int64
	totalQuantity := 0

	for _, item := range request.Items {
		if item.Quantity < 1 {
			return CheckoutResponse{}, errors.New("quantity must be at least 1")
		}
		if item.Quantity > maxQuantityPerItem {
			return CheckoutResponse{}, errors.New("quantity exceeds the per-item limit")
		}
		if totalQuantity+item.Quantity > maxTotalCartQuantity {
			return CheckoutResponse{}, errors.New("cart quantity exceeds the total limit")
		}

		product, exists := productsByID[item.ProductID]
		if !exists {
			return CheckoutResponse{}, errors.New("unknown product ID")
		}

		totalQuantity += item.Quantity
		subtotalPaise += product.PricePaise * int64(item.Quantity)
	}

	couponCode := strings.ToUpper(strings.TrimSpace(request.CouponCode))
	var discountPaise int64

	switch couponCode {
	case "":
		couponCode = ""
	case "SAVE10":
		// Percentage discounts round down to the nearest whole paise.
		discountPaise = subtotalPaise / 10
	case "FLAT100":
		discountPaise = flat100DiscountPaise
		if discountPaise > subtotalPaise {
			discountPaise = subtotalPaise
		}
	default:
		return CheckoutResponse{}, errors.New("invalid coupon code")
	}

	totalPaise := subtotalPaise - discountPaise
	if totalPaise < 0 {
		totalPaise = 0
	}

	return CheckoutResponse{
		SubtotalPaise: subtotalPaise,
		DiscountPaise: discountPaise,
		TotalPaise:    totalPaise,
		CouponCode:    couponCode,
	}, nil
}

package main

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"mime"
	"net/http"
	"strings"
)

const maxRequestBodyBytes = 1 << 20

var allowedOrigins = map[string]bool{
	"http://localhost:5173": true,
	"http://127.0.0.1:5173": true,
}

func newRouter() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/health", healthHandler)
	mux.HandleFunc("/api/products", productsHandler)
	mux.HandleFunc("/api/checkout", checkoutHandler)
	return corsMiddleware(mux)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeMethodNotAllowed(w, http.MethodGet)
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func productsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeMethodNotAllowed(w, http.MethodGet)
		return
	}

	writeJSON(w, http.StatusOK, listProducts())
}

func checkoutHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeMethodNotAllowed(w, http.MethodPost)
		return
	}

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || !strings.EqualFold(mediaType, "application/json") {
		writeError(w, http.StatusUnsupportedMediaType, "Content-Type must be application/json")
		return
	}

	request, status, message := decodeCheckoutRequest(w, r)
	if status != 0 {
		writeError(w, status, message)
		return
	}

	response, err := calculateCheckout(request)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	writeJSON(w, http.StatusOK, response)
}

func decodeCheckoutRequest(w http.ResponseWriter, r *http.Request) (CheckoutRequest, int, string) {
	var request CheckoutRequest
	r.Body = http.MaxBytesReader(w, r.Body, maxRequestBodyBytes)

	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&request); err != nil {
		return CheckoutRequest{}, jsonDecodeErrorStatus(err), jsonDecodeErrorMessage(err)
	}

	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		return CheckoutRequest{}, jsonDecodeErrorStatus(err), jsonDecodeErrorMessage(err)
	}

	return request, 0, ""
}

func jsonDecodeErrorStatus(err error) int {
	var maxBytesError *http.MaxBytesError
	if errors.As(err, &maxBytesError) {
		return http.StatusRequestEntityTooLarge
	}
	return http.StatusBadRequest
}

func jsonDecodeErrorMessage(err error) string {
	var maxBytesError *http.MaxBytesError
	if errors.As(err, &maxBytesError) {
		return "request body is too large"
	}
	return "invalid JSON request"
}

func writeMethodNotAllowed(w http.ResponseWriter, allowedMethod string) {
	w.Header().Set("Allow", allowedMethod+", OPTIONS")
	writeError(w, http.StatusMethodNotAllowed, "method not allowed")
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, ErrorResponse{Error: message})
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(value); err != nil {
		log.Printf("write JSON response: %v", err)
	}
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		origin := r.Header.Get("Origin")
		allowed := allowedOrigins[origin]

		if origin != "" {
			w.Header().Add("Vary", "Origin")
		}
		if allowed {
			w.Header().Set("Access-Control-Allow-Origin", origin)
			w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
			w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
		}

		if r.Method == http.MethodOptions {
			if !allowed {
				writeError(w, http.StatusForbidden, "origin not allowed")
				return
			}
			w.WriteHeader(http.StatusNoContent)
			return
		}

		next.ServeHTTP(w, r)
	})
}

package main

import (
	"log"
	"net/http"
	"time"
)

func main() {
	server := &http.Server{
		Addr:              ":8088",
		Handler:           newRouter(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	log.Printf("checkout API listening on %s", server.Addr)
	if err := server.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"strings"
	"testing"
)

func TestCalculateCheckoutDiscounts(t *testing.T) {
	tests := []struct {
		name         string
		request      CheckoutRequest
		wantSubtotal int64
		wantDiscount int64
		wantTotal    int64
		wantCoupon   string
	}{
		{
			name: "SAVE10 rounds down to a whole paise",
			request: CheckoutRequest{
				Items:      []CheckoutItemRequest{{ProductID: "notebook", Quantity: 1}},
				CouponCode: "SAVE10",
			},
			wantSubtotal: 4999,
			wantDiscount: 499,
			wantTotal:    4500,
			wantCoupon:   "SAVE10",
		},
		{
			name: "FLAT100 applies the fixed discount",
			request: CheckoutRequest{
				Items:      []CheckoutItemRequest{{ProductID: "bag", Quantity: 1}},
				CouponCode: "FLAT100",
			},
			wantSubtotal: 129900,
			wantDiscount: 10000,
			wantTotal:    119900,
			wantCoupon:   "FLAT100",
		},
		{
			name: "FLAT100 cannot reduce the total below zero",
			request: CheckoutRequest{
				Items:      []CheckoutItemRequest{{ProductID: "notebook", Quantity: 1}},
				CouponCode: "FLAT100",
			},
			wantSubtotal: 4999,
			wantDiscount: 4999,
			wantTotal:    0,
			wantCoupon:   "FLAT100",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			got, err := calculateCheckout(test.request)
			if err != nil {
				t.Fatalf("calculateCheckout() error = %v", err)
			}

			if got.SubtotalPaise != test.wantSubtotal {
				t.Errorf("SubtotalPaise = %d, want %d", got.SubtotalPaise, test.wantSubtotal)
			}
			if got.DiscountPaise != test.wantDiscount {
				t.Errorf("DiscountPaise = %d, want %d", got.DiscountPaise, test.wantDiscount)
			}
			if got.TotalPaise != test.wantTotal {
				t.Errorf("TotalPaise = %d, want %d", got.TotalPaise, test.wantTotal)
			}
			if got.CouponCode != test.wantCoupon {
				t.Errorf("CouponCode = %q, want %q", got.CouponCode, test.wantCoupon)
			}
		})
	}
}

func TestCalculateCheckoutRejectsInvalidRequests(t *testing.T) {
	tests := []struct {
		name        string
		request     CheckoutRequest
		wantMessage string
	}{
		{
			name:        "empty cart",
			request:     CheckoutRequest{},
			wantMessage: "cart must contain at least one item",
		},
		{
			name: "unknown product",
			request: CheckoutRequest{
				Items: []CheckoutItemRequest{{ProductID: "missing", Quantity: 1}},
			},
			wantMessage: "unknown product ID",
		},
		{
			name: "zero quantity",
			request: CheckoutRequest{
				Items: []CheckoutItemRequest{{ProductID: "notebook", Quantity: 0}},
			},
			wantMessage: "quantity must be at least 1",
		},
		{
			name: "negative quantity",
			request: CheckoutRequest{
				Items: []CheckoutItemRequest{{ProductID: "notebook", Quantity: -1}},
			},
			wantMessage: "quantity must be at least 1",
		},
		{
			name: "quantity above per-item limit",
			request: CheckoutRequest{
				Items: []CheckoutItemRequest{{ProductID: "notebook", Quantity: maxQuantityPerItem + 1}},
			},
			wantMessage: "quantity exceeds the per-item limit",
		},
		{
			name: "quantity above total limit",
			request: CheckoutRequest{
				Items: []CheckoutItemRequest{
					{ProductID: "notebook", Quantity: maxQuantityPerItem},
					{ProductID: "mug", Quantity: maxQuantityPerItem},
					{ProductID: "bag", Quantity: maxQuantityPerItem},
					{ProductID: "notebook", Quantity: maxQuantityPerItem},
					{ProductID: "mug", Quantity: maxQuantityPerItem},
					{ProductID: "bag", Quantity: maxQuantityPerItem},
				},
			},
			wantMessage: "cart quantity exceeds the total limit",
		},
		{
			name: "invalid coupon",
			request: CheckoutRequest{
				Items:      []CheckoutItemRequest{{ProductID: "notebook", Quantity: 1}},
				CouponCode: "NOT-A-COUPON",
			},
			wantMessage: "invalid coupon code",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			_, err := calculateCheckout(test.request)
			if err == nil {
				t.Fatal("calculateCheckout() error = nil, want an error")
			}
			if !strings.Contains(err.Error(), test.wantMessage) {
				t.Errorf("error = %q, want it to contain %q", err, test.wantMessage)
			}
		})
	}
}

package main

type Product struct {
	ID         string `json:"id"`
	Name       string `json:"name"`
	PricePaise int64  `json:"pricePaise"`
}

type CheckoutItemRequest struct {
	ProductID string `json:"productId"`
	Quantity  int    `json:"quantity"`
}

type CheckoutRequest struct {
	Items      []CheckoutItemRequest `json:"items"`
	CouponCode string                `json:"couponCode,omitempty"`
}

type CheckoutResponse struct {
	SubtotalPaise int64  `json:"subtotalPaise"`
	DiscountPaise int64  `json:"discountPaise"`
	TotalPaise    int64  `json:"totalPaise"`
	CouponCode    string `json:"couponCode,omitempty"`
}

type ErrorResponse struct {
	Error string `json:"error"`
}
